import{_ as n}from"./chunks/2026-08-31-audit-evidence-admissibility-time-plane.DgNldgz5.js";import{_ as i,C as r,o,c as s,a as t,E as d,a2 as c}from"./chunks/framework.Cm6XCzck.js";const y=JSON.parse('{"title":"If It Can Be Explained Afterwards, Was It Knowable Then?","description":"","frontmatter":{"title":"If It Can Be Explained Afterwards, Was It Knowable Then?","date":"2026-08-31","updated":"2026-08-31","column":"open-source-engineering","category":"daily","article_type":"research-methodology","edition":"research-center","research_question":"For the same audit proposition at different evidence cutoffs, how should an Agent Runtime distinguish evidence that exists, evidence that is admissible, and evidence that was available then?","summary":"After replaying 1,187 CatchBench PRE configurations, we apply evidence cutoffs to time-separated artifacts from a real approval probe. The same Reader can make only the judgment allowed by the information budget at each cutoff. This is not a prediction of future duplication; it is a method for fixing the proposition and admissible evidence before evaluating an auditor.","sources":"/en/research/evidence/2026-08-31-runtime-continuity","project_relevance":"substantive-relationship","item_id":"RCR-20260831-03","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-31-audit-evidence-admissibility-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/engineering/2026-08-31-audit-evidence-admissibility.md","filePath":"en/engineering/2026-08-31-audit-evidence-admissibility.md","lastUpdated":1788166937000}'),l={name:"en/engineering/2026-08-31-audit-evidence-admissibility.md"};function h(u,e,p,f,g,m){const a=r("ArticleCover");return o(),s("div",null,[e[0]||(e[0]=t("p",null,[t("a",{href:"/joinwell52/zh/engineering/2026-08-31-audit-evidence-admissibility"},"中文")],-1)),d(a,{image:"/assets/covers/daily-2026-08-31-audit-evidence-admissibility-cover.png",kicker:"Runtime Continuity Research · 03",title:"If It Can Be Explained Afterwards, Was It Knowable Then?",summary:"Retrospective completeness is not contemporaneous knowledge, and existing evidence is not automatically admissible evidence.",version:"RCR-20260831-03",status:"Research Method · 2026-08-31",languageHref:"/zh/engineering/2026-08-31-audit-evidence-admissibility",languageLabel:"中文"}),e[1]||(e[1]=c('<h1 id="if-it-can-be-explained-afterwards-was-it-knowable-then" tabindex="-1">If It Can Be Explained Afterwards, Was It Knowable Then? <a class="header-anchor" href="#if-it-can-be-explained-afterwards-was-it-knowable-then" aria-label="Permalink to &quot;If It Can Be Explained Afterwards, Was It Knowable Then?&quot;">​</a></h1><p>An incident report can look complete: an action created an effect, an audit failed, and recovery created another effect. It is tempting to ask why an Agent did not catch the duplication earlier.</p><p>But were the report&#39;s facts available before the action, while it ran, or only after recovery had finished? Giving an auditor the final artifact set and calling its answer an early warning measures retrospective explanation, not what could have been known then.</p><p>Here “early” does <strong>not</strong> mean predicting that a second effect will certainly occur. It asks a narrower question: <strong>before the second execution, was there already readable evidence that the first effect had happened?</strong> If recovery does not read that evidence, it may treat an identifiable effect fact as unknown.</p><p>The external prompt is <a href="https://arxiv.org/abs/2608.22808" target="_blank" rel="noreferrer">CatchBench</a>, an academic benchmark asking when Agent failure can be caught. It distinguishes three information states: PRE, LIVE, and POST. Its seven task contracts include evidential tasks and Gold-derived mechanism diagnostics; Gold is not a fourth information state. The author, Yue Zhao, is a USC Assistant Professor whose work includes AI auditing, agent safety, and anomaly detection. <a href="https://viterbi.usc.edu/directory/faculty/Zhao/Yue" target="_blank" rel="noreferrer">USC profile</a></p><p>CodeFlowMu is the local multi-Agent collaboration system that we develop and maintain. It records sessions, tool execution, approvals, and results for engineering work. We first replay CatchBench&#39;s public PRE board, then apply time-based evidence cutoffs to artifacts captured from our own approval-fault probe. The resulting question is whether the changed answer comes from a changed method or a changed readable information set.</p><h2 id="_1-the-first-constraint-state-what-was-readable" tabindex="-1">1. The first constraint: state what was readable <a class="header-anchor" href="#_1-the-first-constraint-state-what-was-readable" aria-label="Permalink to &quot;1. The first constraint: state what was readable&quot;">​</a></h2><p>CatchBench&#39;s central reminder is that an audit is often constrained by the record rather than the method. We replayed only its fixed PRE path at <code>874433db</code>, under Python 3.10.11 with <code>python run.py --task pre</code>. We did not run LIVE or POST boards, Gold-derived diagnostics, or CodeFlowMu through CatchBench.</p><p>The output contains 1,187 declared configurations: crewai 298, injecagent 340, mcp 144, n8n 219, sweagent 130, and synthetic 56. They are configurations, not 1,187 newly executed Agent tasks. <a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/fixtures/catchbench-pre.log">Raw PRE output</a></p><table tabindex="0"><thead><tr><th>Method</th><th style="text-align:right;">Precision</th><th style="text-align:right;">Recall</th><th style="text-align:right;">F1</th><th style="text-align:right;">Coverage</th></tr></thead><tbody><tr><td>Flag every risk</td><td style="text-align:right;">0.430</td><td style="text-align:right;">1.000</td><td style="text-align:right;">0.601</td><td style="text-align:right;">1.000</td></tr><tr><td>owasp_asi_combined</td><td style="text-align:right;">0.511</td><td style="text-align:right;">0.910</td><td style="text-align:right;">0.654</td><td style="text-align:right;">1.000</td></tr><tr><td>Cached llama-3.3-70b judgments</td><td style="text-align:right;">0.594</td><td style="text-align:right;">0.839</td><td style="text-align:right;">0.695</td><td style="text-align:right;">0.996</td></tr></tbody></table><p>The last row recomputes scores from existing repository judgments; it makes no new model call. Five configurations are absent from the same scoring set, so the higher number is not a general superiority claim. The always-flag baseline also reaches F1 0.601, and source-level F1 varies substantially. These values constrain method interpretation; they are not a CodeFlowMu score.</p><h2 id="_2-one-run-four-information-budgets" tabindex="-1">2. One run, four information budgets <a class="header-anchor" href="#_2-one-run-four-information-budgets" aria-label="Permalink to &quot;2. One run, four information budgets&quot;">​</a></h2><p>We use one existing real-service probe: an approved synthetic local executor writes its first effect; its audit then fails; a new process later resumes the non-idempotent executor and writes another effect. The effect remains an isolated local file, not a remote service action.</p><p>The research script captures operation-state and effect snapshots at four points. The Reader answers only two propositions: whether independent effect evidence exists at the cutoff, and whether two distinct effects have already occurred at the cutoff. It does not determine business correctness and does not predict a future repeat.</p><table tabindex="0"><thead><tr><th>Cutoff</th><th>Operation state then</th><th>Readable effect evidence</th><th>First effect</th><th>Duplicate already observed</th></tr></thead><tbody><tr><td>T0, approved but not executed</td><td>approved</td><td>no effect file in this budget</td><td>unknown</td><td>unknown</td></tr><tr><td>T1, first effect written</td><td>executing</td><td>1</td><td>yes</td><td>not_observed</td></tr><tr><td>T2, audit failure returned</td><td>failed</td><td>1</td><td>yes</td><td>not_observed</td></tr><tr><td>T3, new-process recovery returned</td><td>succeeded</td><td>2</td><td>yes</td><td>yes</td></tr></tbody></table><p><code>not_observed</code> means “not observed in the current evidence,” not “will never happen.” T0&#39;s <code>unknown</code> means the Reader is not entitled to use the script&#39;s omniscient knowledge.</p><p><img src="'+n+'" alt="A single evidence rail crosses a glass time plane: one cobalt marker is sharp before it and the matching marker is blurred beyond it."></p><p><em>Figure 1. At T2 the Reader may read the first effect but cannot borrow the second effect that appears at T3. A blurred marker means future evidence is not yet admissible, not that it does not exist. Source: RCR-20260831 de-identified E-C1 timeline capture and Reader.</em></p><p>The run produces seven evidence objects: four operation snapshots and three cumulative effect snapshots. At T2 the Reader accepts five objects and rejects two future T3 objects. It can establish the first effect, not an already-observed duplicate. <a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/fixtures/timeline.json">Timeline fixture</a></p><p>The effect snapshots contain 1, 1, and 2 records. Adding rows would misleadingly produce four because the first two snapshots both contain <code>E1</code>; only the last adds <code>E2</code>. The Reader selects the newest snapshot at a cutoff and deduplicates effect IDs. <strong>Evidence cutoff prevents future-information leakage; effect-ID deduplication prevents duplicate observation. They are different controls.</strong></p><h2 id="_3-available-evidence-is-not-admissible-evidence" tabindex="-1">3. Available evidence is not admissible evidence <a class="header-anchor" href="#_3-available-evidence-is-not-admissible-evidence" aria-label="Permalink to &quot;3. Available evidence is not admissible evidence&quot;">​</a></h2><p>The product-independent research Reader first fixes the proposition, then accepts only artifacts with the correct owner, at or before the cutoff, whose content matches the manifest. Only then does it read the newest allowed effect snapshot.</p><p>The four normal cutoffs are paired with four negative controls:</p><table tabindex="0"><thead><tr><th>Change</th><th>Constrained Reader result</th><th>What it prevents</th></tr></thead><tbody><tr><td>N1 removes the effect file</td><td>both propositions <code>unknown</code></td><td>treating <code>failed</code> or executor self-report as effect proof</td></tr><tr><td>N2 inserts another owner&#39;s two effects</td><td>rejects wrong owner; remains <code>unknown</code></td><td>using another run&#39;s duplicate as this run&#39;s duplicate</td></tr><tr><td>N3 supplies T3 output to a T2 input</td><td>rejects after-cutoff items; sees one effect</td><td>presenting future evidence as earlier knowledge</td></tr><tr><td>N4 changes an effect snapshot while retaining its old hash</td><td>rejects integrity/unregistered item</td><td>treating altered data as evidence</td></tr></tbody></table><p>A deliberately weak reader that ignores owner, cutoff, and manifest says “duplicate already happened” for N2 and N3. It is not more intelligent; it has crossed the input boundary.</p><p>This produces the method&#39;s central concept: audit input is not every log one can find. It is the set of evidence admissible for the current <strong>proposition, ownership, cutoff, and integrity</strong> conditions. <code>evidence exists ≠ evidence admissible</code>, and final evidence is not necessarily evidence available at decision time.</p><p>The eight scenarios validate Reader behavior under designed evidence budgets. They are a <strong>decidability experiment</strong>, not a predictive-detection benchmark or a 100% accuracy claim. N3 proves compliance with a temporal information boundary; it does not prove future prediction ability.</p><h2 id="_4-a-runtime-audit-read-contract" tabindex="-1">4. A Runtime audit-read contract <a class="header-anchor" href="#_4-a-runtime-audit-read-contract" aria-label="Permalink to &quot;4. A Runtime audit-read contract&quot;">​</a></h2><p>For CodeFlowMu, SessionStore, operation records, and skill attribution are possible factual sources. The next engineering question is a Runtime Audit Read Contract:</p><ul><li><strong>Proposition</strong> — what exactly is being judged?</li><li><strong>Ownership</strong> — which artifacts belong to this operation or run?</li><li><strong>Cutoff</strong> — until which decision point may they be read?</li><li><strong>Integrity</strong> — which records meet acceptable integrity conditions?</li><li><strong>Unknown semantics</strong> — if evidence is insufficient, is the result <code>unknown</code> or <code>false</code>?</li></ul><p>This is not a new shipped audit Agent, and it does not replace REVIEW or EVAL. It fixes the comparison conditions before deciding whether an improved judge or earlier recording is the right investment.</p><p>The <a href="/joinwell52/en/research/evidence/2026-08-31-runtime-continuity">bilingual evidence guide</a> provides the fixtures, Reader, negative controls, source provenance, and check commands. The product probe requires access to the fixed source; the public package does not claim independent QA or a live monitoring result.</p><p><strong>Reliable audit first fixes the proposition, then the evidence belonging to that judgment, the evidence readable at that time, and the meaning of insufficient evidence. Retrospective completeness does not mean contemporaneous knowledge; contemporaneous knowledge does not mean future prediction.</strong></p>',33))])}const w=i(l,[["render",h]]);export{y as __pageData,w as default};
